CREATE OR REPLACE FUNCTION is_open_between(p_restaurant uuid,p_from timestamptz,p_to timestamptz) RETURNS bool LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE v_tz text; v_day date; BEGIN SELECT r.timezone INTO v_tz FROM restaurants r WHERE r.id=p_restaurant; IF v_tz IS NULL THEN RETURN false; END IF; v_day:=(p_from AT TIME ZONE v_tz)::date; RETURN EXISTS(SELECT 1 FROM(SELECT w.win FROM opening_windows(p_restaurant,v_day-1) w UNION ALL SELECT w.win FROM opening_windows(p_restaurant,v_day) w) windows WHERE windows.win @> tstzrange(p_from,p_to)); END $$;
